(function(){
'use strict';
const $=id=>document.getElementById(id);let serial=0,poll=null,check=null,available=true;
async function api(route,body){const response=await fetch('/api/lifecycle/proxy/'+route,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json','X-PagePoster-Request':'1'},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok)throw Error(data.error||'Не вдалося перевірити проксі.');return data;}
function note(text){const node=$('ap-proxy-note');node.textContent=text;node.hidden=!text;node.classList.toggle('error',!!text);}
function busy(value){for(const id of ['ap-proxy-check','ap-proxy-save','ap-proxy-clear','ap-proxy-list','ap-proxy-enabled'])$(id).disabled=value||!available;}
const states={queued:'Очікує',checking:'Перевіряємо…',ok:'Працює',failed:'Помилка',unknown:'Не підтверджено',busy:'Зайнятий публікацією',cooldown:'Тимчасова пауза',cancelled:'Зупинено'};
const reasons={PROXY_AUTH_FAILED:'Логін або пароль відхилено',PROXY_TIMEOUT:'Не відповів вчасно',PROXY_CONNECT_FAILED:'Немає з’єднання',PROXY_TUNNEL_FAILED:'Не вдалося відкрити тунель',PROXY_CHECK_SERVICE_UNAVAILABLE:'Сервіс визначення IP тимчасово недоступний. Повторіть перевірку.',PROXY_CHECK_RESPONSE_INVALID:'Сервіс не підтвердив зовнішній IP',PROXY_CHECK_FAILED:'Не вдалося перевірити з’єднання',PROXY_CLOSE_FAILED:'Не підтверджено закриття з’єднання'};
function country(code){if(!code)return '—';try{return new Intl.DisplayNames(['uk'],{type:'region'}).of(code)+' ('+code+')';}catch{return code;}}
function render(value){
 check=value;const body=$('ap-proxy-results-body');body.replaceChildren();$('ap-proxy-results').hidden=!value;$('ap-proxy-cancel').hidden=value?.state!=='running';if(!value)return;
 $('ap-proxy-progress').textContent=(value.state==='running'?'Перевіряємо':value.state==='cancelled'?'Зупинено':'Перевірено')+': '+value.completed+' / '+value.total+'. Працюють: '+value.rows.filter(row=>row.state==='ok').length+'. '+(value.source==='draft'?'Вставлений список; для публікації збережіть його.':'Збережений список.');
 for(const row of value.rows){const tr=document.createElement('tr');for(const text of [row.index+'. '+row.server,(states[row.state]||row.state)+(reasons[row.code]?' · '+reasons[row.code]:''),row.ip||'—',country(row.country),row.responseMs===null?'—':row.responseMs+' мс']){const td=document.createElement('td');td.textContent=text;tr.appendChild(td);}body.appendChild(tr);}
 $('ap-proxy-check-time').textContent=value.finishedAt?'Перевірено: '+new Date(value.finishedAt).toLocaleString('uk-UA')+'. IP і країна за даними country.is на момент перевірки. Доступ до конкретного WordPress може відрізнятися.':'';
}
function schedule(current){clearTimeout(poll);if(check?.state==='running')poll=setTimeout(()=>void refresh(current),1000);}
async function refresh(current){busy(true);try{const data=await api('checks');if(current!==serial)return;render(data.check);busy(check?.state==='running');schedule(current);}catch(error){if(current===serial){note(error.message);busy(false);}}}
async function start(){const current=++serial;clearTimeout(poll);busy(true);note('');try{const {proxy}=await api('settings');if(current!==serial)return;const data=await api('checks',{expectedRevision:proxy.revision,list:$('ap-proxy-list').value});if(current!==serial)return;render(data.check);busy(check?.state==='running');schedule(current);}catch(error){if(current===serial){note(error.message);busy(false);}}}
async function cancel(){if(!check)return;const current=serial;$('ap-proxy-cancel').disabled=true;try{const data=await api('checks/cancel',{id:check.id});if(current!==serial)return;clearTimeout(poll);render(data.check);busy(false);}catch(error){if(current===serial)note(error.message);}finally{$('ap-proxy-cancel').disabled=false;}}
function init(){if(!$('ap-proxy-check'))return;$('ap-proxy-check').addEventListener('click',()=>void start());$('ap-proxy-cancel').addEventListener('click',()=>void cancel());$('ap-proxy-list').addEventListener('input',()=>{if(check?.source==='draft'&&check.state!=='running')render(null);});window.addEventListener('pageposter:proxy-saved',()=>{serial++;clearTimeout(poll);render(null);});window.addEventListener('pageposter:settings-opened',()=>{serial++;clearTimeout(poll);busy(true);});window.addEventListener('pageposter:proxy-settings-loaded',event=>{available=event.detail.available;if(available)void refresh(serial);else busy(true);});$('ap-settings').addEventListener('close',()=>{serial++;clearTimeout(poll);});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
